text:
{
  "title": "اتفاقية الخدمات ومعالجة البيانات",
  "planted": [
    {
      "slot": "p1",
      "text": "يُصرح للمورد بموجب هذه الاتفاقية الاستعانة بأي مقاول فرعي لتنفيذ أعمال معالجة البيانات دون الحاجة لتقديم إشعار مسبق للشركة، كما تُعفى أنشطة المورد التشغيلية من أي عمليات تدقيق أو تفتيش دوري تجريها الشركة."
    },
    {
      "slot": "p2",
      "text": "توافق الأطراف على حفظ سجلات البيانات والمعلومات المتعلقة بالخدمة في أرشيف المورد لأجل غير مسمى بغرض استمرارية العمل وتحسين الجودة في المستقبل، دون التزام بإزالتها أو التخلص منها نهائياً."
    },
    {
      "slot": "p3",
      "text": "تقتصر أغراض معالجة البيانات الشخصية حصرياً على تنفيذ المهام التشغيلية المتفق عليها ضمن نطاق الخدمات المقدمة ولا تستخدم لأي غرض آخر."
    },
    {
      "slot": "p4",
      "text": "يلتزم المورد بإخطار الشركة فور وقوع أي حادث أمني أو وصول غير مصرح به للبيانات خلال مدة أقصاها أربع وعشرون ساعة، لتقوم الشركة باتخاذ الإجراءات اللازمة وإبلاغ الجهات المعنية."
    }
  ],
  "neutral": [
    "تستحق الشركة مقابل مالي نظير الخدمات المقدمة وفقاً للجداول المالية الملحقة بهذه الاتفاقية، وتُسدد الفواتير خلال ثلاثين روزنامة من تاريخ إصدارها.",
    "تبدأ هذه الاتفاقية من تاريخ توقيع الطرفين وتظل سارية لمدة عام ميلادي واحد، وتجدد تلقائياً ما لم يبلغ أحد الطرفين برغبته في الإنهاء كتابة قبل موعدها بتسعين يوماً.",
    "تظل حقوق الملكية الفكرية لجميع البرمجيات والأنظمة المستخدمة ملكاً خالصاً للمورد، ولا تمنح هذه الاتفاقية أي حقوق ملكية للطرف الآخر.",
    "تخضع هذه الاتفاقية وتفسر وفقاً لأنظمة المملكة العربية السعودية، وفي حال النزاع تختص المحاكم المختصة بمدينة الرياض بالفصل فيه.",
    "تُوجه كافة الإشعارات والمراسلات الرسمية بين الطرفين كتابة عبر العناوين البريدية المعتمدة والمذكورة في ديباجة هذه الاتفاقية."
  ]
}
